<label id="original-label"><input type="hidden" name="original_audio" value="0"><input type="checkbox" name="original_audio" value="1" checked> Manter o som original dos vídeos</label>
<p class="notice" id="cost">Gerar usa 1 cota do VideoGenius. Sem narração, não usa créditos de voz.</p>
<p>Fotos são exibidas como cenas; este modo não anima pessoas. Com narração, o áudio original é substituído e a duração acompanha a fala.</p>
<button id="generate" disabled>Gerar vídeo · 1 cota</button></form></main>
<script>
const selected=[];const picks=[...document.querySelectorAll('.pick')];
function render(){document.querySelector('#order').replaceChildren();document.querySelector('#ids').replaceChildren();selected.forEach((id,index)=>{const pick=picks.find(x=>x.value===id);const li=document.createElement('li');li.append(document.createTextNode(pick.dataset.name));for(const [text,delta] of [['↑',-1],['↓',1]]){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=index+delta<0||index+delta>=selected.length;b.onclick=()=>{[selected[index],selected[index+delta]]=[selected[index+delta],selected[index]];render()};li.append(b)}document.querySelector('#order').append(li);const input=document.createElement('input');input.type='hidden';input.name='media_ids[]';input.value=id;document.querySelector('#ids').append(input)});document.querySelector('#generate').disabled=!selected.length;}
picks.forEach(p=>p.onchange=()=>{if(p.checked){if(selected.length>=12){p.checked=false;alert('Selecione até 12 arquivos.');return}selected.push(p.value)}else selected.splice(selected.indexOf(p.value),1);render()});
function voice(){const on=document.querySelector('#narration').value==='1';document.querySelector('#voice-fields').hidden=!on;document.querySelector('#script').required=on;document.querySelector('#original-label').hidden=on;document.querySelector('#cost').textContent='Gerar usa 1 cota do VideoGenius. '+(on&&document.querySelector('#provider').value==='elevenlabs'?'Também consome créditos ElevenLabs conforme o texto e a voz.':'Não usa créditos ElevenLabs.');}document.querySelector('#narration').onchange=voice;document.querySelector('#provider').onchange=voice;
document.querySelector('#create').onsubmit=()=>{document.querySelector('#generate').disabled=true;document.querySelector('#generate').textContent='Enviando…'};
document.querySelector('#upload').onchange=async function(){const status=document.querySelector('#upload-status');this.disabled=true;let done=0;try{for(const file of this.files){if(file.size>100*1024*1024)throw Error('Arquivo maior que 100 MB: '+file.name);await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/media');xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-CSRF-TOKEN',document.querySelector('input[name=_token]').value);xhr.upload.onprogress=e=>status.textContent='Enviando '+file.name+': '+(e.lengthComputable?Math.round(e.loaded/e.total*100)+'%':'…');xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300)return resolve();let message='Não foi possível enviar. Confira o tamanho do arquivo e sua conexão.';try{const body=JSON.parse(xhr.responseText);message=Object.values(body.errors||{}).flat().join(' ')||body.message||message}catch{}reject(Error(message))};xhr.onerror=()=>reject(Error('Conexão interrompida. Tente novamente.'));const data=new FormData();data.append('file',file);xhr.send(data)});done++;}status.textContent=done+' arquivo(s) enviado(s). Toque em Ver arquivos enviados.';}catch(e){status.textContent=e.message;}finally{this.disabled=false;if(done)document.querySelector('#refresh').hidden=false;}};
</script></html>
